# -*- coding: utf-8 -*-
"""Builds all inner pages of radicalpolymer.com from index.html's header/footer + content.py.
Run from repo root:  python3 _build/build.py
"""
import os, re, html, sys
sys.path.insert(0, os.path.dirname(__file__))
from content import *

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
IDX = open(os.path.join(ROOT, 'index.html'), encoding='utf-8').read()
esc = html.escape

def U(key, w=1200, q=75):
    pid = IMG.get(key, key)
    return f'https://images.unsplash.com/photo-{pid}?auto=format&fit=crop&w={w}&q={q}'

def img(key, w=1200, alt='', eager=False):
    lz = '' if eager else ' loading="lazy"'
    return f'<img src="{U(key, w)}" alt="{esc(alt)}"{lz}>'

def between(a, b):
    i = IDX.index(a); j = IDX.index(b, i)
    return IDX[i:j]

# ---------- shared assets ----------
def build_assets():
    css = re.search(r'<style>(.*?)</style>', IDX, re.S).group(1)
    inner = open(os.path.join(ROOT, '_build', 'inner.css'), encoding='utf-8').read()
    os.makedirs(os.path.join(ROOT, 'assets', 'css'), exist_ok=True)
    open(os.path.join(ROOT, 'assets', 'css', 'style.css'), 'w', encoding='utf-8').write('/* Generated by _build/build.py from index.html + _build/inner.css */\n' + css.strip() + '\n' + inner)

HEAD_LINKS = re.search(r'(<link rel="preconnect".*?font-awesome[^>]*>)', IDX, re.S).group(1)
TOP = between('<div class="prog"></div>', '<!-- 3. HERO -->')
FOOT = between('<!-- 19. FOOTER -->', '<script>')
ENQ = between('<!-- 18. ENQUIRY + MAP -->', '<!-- 19. FOOTER -->')
TOP = TOP.replace('<li class="act"><a href="index.html">Home</a></li>', '<li><a href="index.html">Home</a></li>')

NAV_KEYS = {'about': 'about-us.html', 'products': 'products.html', 'industries': 'industries.html', 'manufacturing': 'manufacturing.html',
            'why': 'why-choose-us.html', 'testimonials': 'testimonials.html', 'blog': 'blog.html', 'contact': 'contact-us.html'}

def header(active):
    t = TOP
    if active in NAV_KEYS:
        href = NAV_KEYS[active]
        t = t.replace(f'<li><a href="{href}">', f'<li class="act"><a href="{href}">', 1)
        t = t.replace(f'<li class="has-dd"><a href="{href}">', f'<li class="has-dd act"><a href="{href}">', 1)
    return t

def page(fname, title, desc, active, body, product=None):
    enq_present = 'id="enquiry"' in body
    out = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{esc(title)}</title>
<meta name="description" content="{esc(desc)}">
<meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website">
<link rel="icon" href="logo.png">
{HEAD_LINKS}
<link rel="stylesheet" href="assets/css/style.css">
</head>
<body>
{header(active)}
<main>
{body}
</main>
{FOOT}<script src="assets/js/main.js"></script>
</body>
</html>
'''
    if product:
        out = out.replace(f'<option>{product}</option>', f'<option selected>{product}</option>')
    open(os.path.join(ROOT, fname), 'w', encoding='utf-8').write(out)
    PAGES.append(fname)

PAGES = []

# ---------- components ----------
def phero(crumbs, eyebrow, title, sub, im, chips=(), card=True, acts=True, extra=''):
    cr = '<a href="index.html"><i class="fa-solid fa-house" style="font-size:12px;color:var(--gold2)"></i> Home</a>'
    for c in crumbs:
        cr += f' <i class="fa-solid fa-chevron-right"></i> ' + (f'<a href="{c[1]}">{c[0]}</a>' if len(c) > 1 else f'<span>{c[0]}</span>')
    ch = ''.join(f'<span><i class="fa-solid fa-circle-check"></i>{c}</span>' for c in chips)
    a = ('<div class="acts"><a href="#" class="btn btn-g" data-open-enquiry>Get a Free Quote <i class="fa-solid fa-arrow-right"></i></a>'
         '<a href="tel:+919711114333" class="btn btn-l"><i class="fa-solid fa-phone"></i> +91 9711114333</a></div>') if acts else ''
    cd = '''<div class="ph-card"><div class="row"><i class="fa-solid fa-phone"></i><div><small>Call Us</small><b><a href="tel:+919711114333">+91 9711114333</a></b></div></div>
<div class="row"><i class="fa-regular fa-envelope"></i><div><small>Email Us</small><b><a href="mailto:sales@radicalpolymer.com">sales@radicalpolymer.com</a></b></div></div>
<div class="row"><i class="fa-regular fa-clock"></i><div><small>Working Hours</small><b>Mon – Sat: 9:30 AM – 7:00 PM</b></div></div>
<a href="#" class="btn btn-g" data-open-enquiry>Request a Quote <i class="fa-solid fa-paper-plane"></i></a></div>''' if card else ''
    return f'''<section class="phero"><div class="bg">{img(im, 1900, '', True)}</div><div class="wrap">
 <div><nav class="crumb" aria-label="Breadcrumb">{cr}</nav><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p class="sub">{sub}</p>{extra}{a}{f'<div class="chips">{ch}</div>' if ch else ''}</div>
 {cd}
</div></section>'''

def head(eyebrow, title, lead='', center=False, side=''):
    l = f'<p class="lead">{lead}</p>' if lead else ''
    if center:
        return f'<div class="center rv" style="margin-bottom:50px"><span class="eyebrow">{eyebrow}</span><h2 class="h2">{title}</h2>{l}</div>'
    return f'<div class="sec-head rv"><div><span class="eyebrow">{eyebrow}</span><h2 class="h2" style="margin:0">{title}</h2></div>{side or l}</div>'

