def mat_table(side=True):
    rows = ''.join(f'<tr><td>{n}</td><td>{b}</td><td>{t}</td><td><div class="bar"><i style="--w:{o}%"></i></div></td></tr>' for n, s, b, t, o in MATERIALS)
    tbl = f'<div class="tbl-wrap rv"><table class="mat-t"><thead><tr><th>Material</th><th>Best For</th><th>Temp. Range (approx.)</th><th>Oil Resistance</th></tr></thead><tbody>{rows}</tbody></table></div>'
    if not side:
        return tbl
    return f'''<div class="mat-wrap">{tbl}<div class="mat-side img rv d1">{img("lab", 800)}<div><h3>Not sure which material?</h3><p>Share your temperature, media and pressure — we'll recommend the right compound.</p><a href="#" class="btn btn-g" data-open-enquiry>Ask Our Expert <i class="fa-solid fa-comments"></i></a></div></div></div>'''

