def process_tl(soft=False, title='Our Work <em>Process</em>'):
    items = ''
    for k, (ic, t, d, im) in enumerate(PROCESS):
        box = f'<div class="box rv"><div class="img">{img(im, 400)}</div><div class="tx"><small>STEP 0{k+1}</small><h3><i class="{ic}" style="color:var(--gold)"></i>{t}</h3><p>{d}</p></div></div>'
        items += (f'<div class="ts">{box}<div class="dot">0{k+1}</div></div>' if k % 2 == 0 else f'<div class="ts right"><div class="dot">0{k+1}</div>{box}</div>')
    return f'''<section class="sec{" u-soft" if soft else ""}"><div class="wrap">
 <div class="center rv"><span class="eyebrow"><i class="fa-solid fa-diagram-project"></i> How It Works</span><h2 class="h2">{title}</h2><p class="lead">From your first enquiry to final dispatch — a simple, transparent four-step process.</p></div>
 <div class="tl"><div class="fill"></div>{items}</div>
</div></section>'''

def steps4(items=None, dark=False):
    items = items or [(ic, t, d) for ic, t, d, _ in PROCESS]
    return '<div class="steps4">' + ''.join(f'<div class="st4 rv d{k}"><span class="n">0{k+1}</span><i class="{ic}"></i><h3>{t}</h3><p>{d}</p></div>' for k, (ic, t, d) in enumerate(items)) + '</div>'

